import React from 'react';

const AracKontrol = () => {
    return (
        <div className="min-h-screen bg-gray-100 p-8">
            <h1 className="text-3x1 font-bold text-center mb-8">Araç Kontrol</h1>
            <p className="text-center text-gray-600">Araç kontrol sayfası buraya gelecek!</p>
        </div>
    );
};

export default AracKontrol;
